def source_groups(arr, colors, connectivity=4):
    H,W=arr.shape
    seen=set(); groups=[]
    steps=([(-1,0),(1,0),(0,-1),(0,1)] if connectivity==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc])
    for r in range(H):
      for c in range(W):
        if int(arr[r,c]) not in colors or (r,c) in seen:continue
        q=[(r,c)];seen.add((r,c));g=[]
        for x,y in q:
          g.append((x,y))
          for dr,dc in steps:
            z=(x+dr,y+dc)
            if 0<=z[0]<H and 0<=z[1]<W and int(arr[z]) in colors and z not in seen:
              seen.add(z);q.append(z)
        groups.append(g)
    return groups

def fill_nearest_groups(arr, target, seedcolors, preserve_center3x3=True):
    H,W=arr.shape
    groups=source_groups(arr,seedcolors,4)
    groupcols=[Counter(int(arr[p]) for p in g).most_common(1)[0][0] for g in groups]
    distances=[]
    for g in groups:
      d={p:0 for p in g};q=deque(g)
      while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
          if 0<=nr<H and 0<=nc<W and int(arr[nr,nc])==target and (nr,nc) not in d:
            d[(nr,nc)]=d[(r,c)]+1;q.append((nr,nc))
      distances.append(d)
    out=arr.copy()
    # detect 3x3 full target, central square only; there can be multiple so list
    squares=[]
    if preserve_center3x3:
      for r in range(H-2):
       for c in range(W-2):
        if np.all(arr[r:r+3,c:c+3]==target): squares.append((r,c))
    for r,c in zip(*np.where(arr==target)):
      if any(rr<=r<=rr+2 and cc<=c<=cc+2 for rr,cc in squares):
        # preserve border; center gets global majority over all seed pixels
        continue
      ds=[d.get((r,c),999) for d in distances]
      m=min(ds); inds=[i for i,d in enumerate(ds) if d==m]
      labels={groupcols[i] for i in inds}
      if m<999 and len(labels)==1: out[r,c]=labels.pop()
    # special center(s)
    if squares:
      allseed=[int(arr[p]) for g in groups for p in g]
      globalc=Counter(allseed).most_common(1)[0][0]
      for rr,cc in squares:out[rr+1,cc+1]=globalc
    return out, groups, groupcols, distances, squares
